package marked

import (
	"encoding/json"
	"os"
	"path/filepath"
	"testing"
)

// TestPiMarkdownParity compares pi's markdown stack of the port against the
// same stack of marked 18.0.11: the emStrong tokenizer of
// marked-cjk-friendly 0.1.2, the strict strikethrough tokenizer, and the
// latex extensions.
//
// The reference is generated by scripts/pi-marked-reference.mjs.
func TestPiMarkdownParity(t *testing.T) {
	cases := loadPiCases(t)

	instance := NewPiMarked()
	for _, testCase := range cases {
		testCase := testCase
		t.Run(testCase.Markdown, func(t *testing.T) {
			tokens := instance.Lexer(testCase.Markdown, nil)

			got := canonicalTokens(tokens)
			if normalizeJSON(got) != normalizeJSON(testCase.Tokens) {
				t.Fatalf("token stream differs for %q\ngot:  %s\nwant: %s",
					testCase.Markdown, compactJSON(got), compactJSON(testCase.Tokens))
			}
		})
	}
}

// piCase is one case of the pi markdown reference.
type piCase struct {
	Markdown string `json:"markdown"`
	Tokens   []any  `json:"tokens"`
}

// TestTrimPartialClosingFences checks the streamed closing fence fix-up of
// pi. A partial closing fence must not stay in the code of the block.
func TestTrimPartialClosingFences(t *testing.T) {
	tests := []struct {
		name  string
		input string
		text  string
	}{
		// A closed fence ends with a newline, so the last line of the raw is
		// empty and the trim does not run.
		{"full fence", "```go\ncode\n```\n", "code"},
		// A streamed partial fence is the last line of the raw without a
		// newline, so the trim removes it.
		{"partial fence", "```go\ncode\n``", "code"},
		{"single tick", "```go\ncode\n`", "code"},
		{"tilde partial", "~~~\ncode\n~~", "code"},
		{"wrong marker", "```go\ncode\n--", "code\n--"},
		{"longer than marker", "```go\ncode\n````\n", "code"},
	}

	for _, test := range tests {
		test := test
		t.Run(test.name, func(t *testing.T) {
			tokens, _ := Lex(test.input, nil)
			TrimPartialClosingFences(tokens)
			if len(tokens) == 0 || tokens[0].Type != TypeCode {
				t.Fatalf("expected a code token, got %+v", tokens)
			}
			if tokens[0].Text != test.text {
				t.Fatalf("text differs for %q: got %q, want %q",
					test.input, tokens[0].Text, test.text)
			}
		})
	}
}

// TestTrimPartialClosingFencesWalksContainers checks that the fix-up finds
// the code block inside lists and block quotes.
func TestTrimPartialClosingFencesWalksContainers(t *testing.T) {
	tokens, _ := Lex("- item\n  ```go\n  code\n  ``", nil)
	TrimPartialClosingFences(tokens)
	if len(tokens) != 1 || tokens[0].Type != TypeList || len(tokens[0].Items) != 1 {
		t.Fatalf("expected a one item list, got %+v", tokens)
	}
	itemTokens := tokens[0].Items[0].Tokens
	if len(itemTokens) == 0 || itemTokens[len(itemTokens)-1].Type != TypeCode {
		t.Fatalf("expected the list item to end with a code token, got %+v", itemTokens)
	}
	if got := itemTokens[len(itemTokens)-1].Text; got != "code" {
		t.Fatalf("text differs: got %q, want %q", got, "code")
	}
}

// loadPiCases reads the pi markdown reference.
func loadPiCases(t *testing.T) []piCase {
	t.Helper()
	path := filepath.Join("testdata", "pi.json")
	data, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("read reference: %v", err)
	}
	var cases []piCase
	if err := json.Unmarshal(data, &cases); err != nil {
		t.Fatalf("parse reference: %v", err)
	}
	if len(cases) == 0 {
		t.Fatal("reference is empty")
	}
	return cases
}
